package org.sleepwell.app;

import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public class RecordModelTest {
    private static long t(String iso){return Instant.parse(iso).toEpochMilli();}
    private RecordEntry record(long start,long end,Long active,String source,RecordDraft draft,List<RecordIntervals.Span> pauses){return new RecordEntry(1,start,end,active,source,"local","UTC",0,0,draft,false,0,pauses);}
    @Test public void awakeAndPauseUnionIsExcludedOnlyOnce(){RecordDraft d=new RecordDraft(1000,11000);RecordEntry r=record(1000,11000,8000L,"tracked",d,List.of(new RecordIntervals.Span(3000,5000)));d.awake.add(new RecordIntervals.Span(4000,7000));assertEquals(6000,r.draft(d).duration());}
    @Test public void trimIntersectsActualActiveIntervalsRatherThanScaling(){RecordDraft d=new RecordDraft(1000,11000);RecordEntry r=record(1000,11000,6000L,"tracked",d,List.of(new RecordIntervals.Span(3000,7000)));d.start=7000;assertEquals(4000,r.draft(d).duration());d.end=9000;assertEquals(2000,r.draft(d).duration());}
    @Test public void untouchedMonotonicProgressRemainsAuthoritative(){RecordDraft d=new RecordDraft(1000,11000);RecordEntry r=record(1000,11000,7000L,"tracked",d,List.of());assertEquals(7000,r.duration());assertEquals(7000,RecordIntervals.length(r.coverage()));d.start=8000;assertEquals(0,r.draft(d).duration());}
    @Test public void overlappingAdjacentAwakesAndAllAwakeAreValid(){RecordDraft d=new RecordDraft(1000,11000);d.awake.add(new RecordIntervals.Span(1000,6000));d.awake.add(new RecordIntervals.Span(5000,8000));d.awake.add(new RecordIntervals.Span(8000,11000));d.validate(1000,11000,false,20000);assertEquals(0,record(1000,11000,null,"tracked",d,List.of()).draft(d).duration());}
    @Test public void trimmingDropsAwakeCoverageOutsideTheNewBounds(){RecordDraft d=new RecordDraft(4000,10000);d.awake.add(new RecordIntervals.Span(1000,5000));assertEquals(5000,record(1000,11000,null,"tracked",d,List.of()).draft(d).duration());}
    @Test public void manualPeriodCanChangeWithoutInventingSensorCoverage(){RecordDraft d=new RecordDraft(1000,11000);RecordEntry r=record(1000,11000,null,"manual",d,List.of());d.start=500;d.end=12000;assertEquals(11500,r.draft(d).duration());assertEquals("User-reported",r.draft(d).provenance());}
    @Test public void tracksCannotExtendAndManualCannotEndInFuture(){RecordDraft d=new RecordDraft(500,11000);try{d.validate(1000,11000,false,20000);fail();}catch(IllegalArgumentException expected){}d.start=1000;try{d.validate(1000,11000,true,10000);fail();}catch(IllegalArgumentException expected){}}
    @Test public void tagNormalizationDeduplicatesWithoutLosingUnicode(){RecordDraft d=new RecordDraft(1000,2000);d.addTag(" #Late   meal ");d.addTag("late meal");d.addTag("قهوة");assertEquals(List.of("Late meal","قهوة"),d.tags);}
    @Test public void dstGapRejectsAndFoldRequiresAnOffset(){ZoneId zone=ZoneId.of("Europe/Berlin");try{RecordDraft.instant(LocalDateTime.parse("2026-03-29T02:30"),zone,null);fail();}catch(IllegalArgumentException expected){}LocalDateTime fold=LocalDateTime.parse("2026-10-25T02:30");try{RecordDraft.instant(fold,zone,null);fail();}catch(IllegalArgumentException expected){}assertEquals(3600000,RecordDraft.instant(fold,zone,ZoneOffset.ofHours(1))-RecordDraft.instant(fold,zone,ZoneOffset.ofHours(2)));}
    @Test public void sleepDayUsesLocalCalendarBoundary(){RecordDraft d=new RecordDraft(t("2026-10-22T22:00:00Z"),t("2026-10-23T07:00:00Z"));RecordEntry r=record(d.start,d.end,null,"manual",d,List.of());assertEquals(LocalDate.parse("2026-10-23"),r.day(0));assertEquals(LocalDate.parse("2026-10-22"),r.day(12*60));}
    @Test public void overlapsAndNapsMergeWithoutDoubleCounting(){long start=t("2026-10-22T22:00:00Z"),end=t("2026-10-23T06:00:00Z");RecordEntry a=record(start,end,null,"manual",new RecordDraft(start,end),List.of()),b=record(end-3600000,end+3600000,null,"manual",new RecordDraft(end-3600000,end+3600000),List.of());RecordTrends.Range range=RecordTrends.range(LocalDate.parse("2026-10-23"),0);Collection<RecordTrends.Day> days=RecordTrends.days(List.of(a,b),range,0).values();assertEquals(1,days.size());assertEquals(9*3600000L,RecordTrends.average(days));assertEquals(-3600000,RecordTrends.goalGap(days,8*3600000L));}
    @Test public void missingDaysAreNotZeroSleepAndNapHasNoBedtime(){long start=t("2026-10-23T14:00:00Z"),end=start+1200000;RecordDraft d=new RecordDraft(start,end);d.addTag("Nap");RecordEntry nap=record(start,end,null,"manual",d,List.of());SortedMap<LocalDate,RecordTrends.Day> days=RecordTrends.days(List.of(nap),RecordTrends.range(LocalDate.parse("2026-10-23"),0),0);assertEquals(1,days.size());assertEquals(1200000,RecordTrends.average(days.values()));assertNull(days.get(LocalDate.parse("2026-10-23")).bedtime());}
    @Test public void monthAndYearUseRealCalendarLengths(){RecordTrends.Range month=RecordTrends.range(LocalDate.parse("2028-02-15"),1),year=RecordTrends.range(LocalDate.parse("2028-02-15"),2);assertEquals(LocalDate.parse("2028-02-29"),month.end);assertEquals(366,java.time.temporal.ChronoUnit.DAYS.between(year.start,year.end)+1);}
    @Test public void circularBedtimesKeepMidnightAdjacent(){assertEquals(20,RecordTrends.nightMinute(10)-RecordTrends.nightMinute(23*60+50));}
    @Test public void inconsistentMonotonicMetadataIsLimitedWithoutInventingCoverage(){RecordEntry r=record(1000,11000,20000L,"legacy",new RecordDraft(1000,11000),List.of());assertEquals(10000,r.duration());assertTrue(r.durationLimited());}
    @Test public void crossEndDayOverlapsHaveSingleOwnership(){long a=t("2026-10-22T22:00:00Z"),b=t("2026-10-23T07:00:00Z"),c=t("2026-10-23T06:00:00Z"),d=t("2026-10-24T07:00:00Z");RecordEntry one=record(a,b,null,"manual",new RecordDraft(a,b),List.of()),two=record(c,d,null,"manual",new RecordDraft(c,d),List.of());SortedMap<LocalDate,RecordTrends.Day> days=RecordTrends.days(List.of(one,two),RecordTrends.range(LocalDate.parse("2026-10-24"),0),0);assertEquals(9*3600000L,days.get(LocalDate.parse("2026-10-23")).duration());assertEquals(24*3600000L,days.get(LocalDate.parse("2026-10-24")).duration());}
    @Test public void clippedUnionHandlesZeroAndNestedIntervals(){assertEquals(0,RecordIntervals.length(List.of()));assertEquals(10,RecordIntervals.length(List.of(new RecordIntervals.Span(1,11),new RecordIntervals.Span(3,6))));assertEquals(3,RecordIntervals.length(RecordIntervals.intersect(List.of(new RecordIntervals.Span(1,11)),8,14)));}
}
